<span class="line">    <span class="token keyword">const</span> delay <span class="token operator">=</span> <span class="token function">parseFloat</span><span class="token punctuation">(</span>style<span class="token punctuation">.</span>transitionDelay<span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
